            continue

        intervals = []
        for participant in participants:
            for start, end in busy[participant].get(day, []):
                intervals.append((to_minutes(start), to_minutes(end)))

        for start in range(work_start, work_end - duration + 1):
            end = start + duration
            if all(not (start < s and end > e) for s, e in intervals):
